css:
.print-format {
  margin: 0;
  padding: 0;
  font-family: "DejaVu Sans", Arial, sans-serif;
  color: #1f3350;
}

.voucher-shell {
  width: 100%;
  border: 1px solid #b9c4cf;
  border-radius: 2px;
  overflow: hidden;
}

.voucher {
  width: 100%;
  min-height: 280px;
  border-collapse: collapse;
}

.left-side {
  width: 38%;
  vertical-align: top;
  background: linear-gradient(180deg, #d8e7f2 0%, #e7f0f5 100%);
  position: relative;
  overflow: hidden;
  padding: 18px 14px 14px 14px;
}

.left-side::after {
  content: "";
  position: absolute;
  top: 0;
  right: -52px;
  width: 112px;
  height: 100%;
  border-radius: 70px;
  background: rgba(219, 234, 222, 0.65);
  z-index: 1;
}

.left-content {
  position: relative;
  z-index: 2;
  min-height: 245px;
}

.logo-wrap {
  text-align: center;
  margin-top: 6px;
}

.logo-wrap img {
  max-width: 130px;
  max-height: 110px;
}

.left-contact {
  position: absolute;
  left: 8px;
  right: 8px;
  bottom: 4px;
  text-align: center;
  color: #1f3350;
  font-size: 10px;
  line-height: 1.35;
}

.right-side {
  width: 62%;
  vertical-align: top;
  background: #ffffff;
  padding: 12px 14px 10px 16px;
}

.voucher-title {
  margin: 0 0 8px 0;
  color: #1f5d90;
  font-family: "Brush Script MT", "Segoe Script", cursive;
  font-size: 44px;
  line-height: 1;
  font-weight: 400;
}

.detail-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 24px;
}

.detail-table td {
  vertical-align: bottom;
  padding: 2px 0;
}

.detail-label {
  width: 40%;
  white-space: nowrap;
  padding-right: 10px;
  color: #1f3350;
}

.detail-value {
  width: 60%;
  border-bottom: 1px solid #cad4de;
  min-height: 20px;
  color: #0f4f8a;
  font-family: "DejaVu Sans", Arial, sans-serif;
  line-height: 1.25;
  word-break: break-word;
}

.service-value {
  min-height: 30px;
  line-height: 1.25;
}

.service-row .detail-value {
  padding-bottom: 4px;
}
